import harness as h
import subprocess,json
payload={'base':h.ENV['baseUrl'],'username':h.CONFIG.get('VAHAN_UI_AUTH_USERNAME','admin'),'password':h.CONFIG['VAHAN_UI_AUTH_PASSWORD']}
script="""const {chromium}=require('playwright');const net=require('node:net');const cfg=JSON.parse(process.env.D3_INPUT);
(async()=>{const forward=net.createServer(s=>{const u=net.connect(15187,'host.docker.internal');s.pipe(u);u.pipe(s);s.on('error',()=>u.destroy());u.on('error',()=>s.destroy())});await new Promise(r=>forward.listen(15187,'127.0.0.1',r));const browser=await chromium.launch({headless:true,chromiumSandbox:true});const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto(cfg.base);await page.getByLabel('Username',{exact:true}).fill(cfg.username);await page.getByLabel('Password',{exact:true}).fill(cfg.password);await page.getByRole('button',{name:'Sign in',exact:true}).click();await page.getByRole('navigation',{name:'Main navigation'}).waitFor();await page.goto(cfg.base+'/#run-history');await page.waitForTimeout(2500);const history=await page.evaluate(async()=>{const r=await fetch('/api/annual-reports/run-history',{headers:{Authorization:'Bearer '+localStorage.getItem('vahanUiAccessToken')}});return r.json()});const rows=await page.locator('.run-history-table tbody tr').count();if(rows!==history.runs.length||rows!==4)throw Error('Expected exactly4 UI/API history rows');if(history.runs.some(r=>r.pending||r.running||r.failed||r.processed!==r.totalCases))throw Error('History does not contain terminal successful real runs');await page.screenshot({path:'/tmp/d3-history-final.png',fullPage:true});console.log(JSON.stringify({history,uiRows:rows,body:await page.locator('body').innerText(),errors}));await browser.close();await new Promise(r=>forward.close(r))})().catch(e=>{console.error(e.message);process.exit(1)});"""
wrapped='process.env.D3_INPUT='+json.dumps(json.dumps(payload))+';\n'+script
container=h.ENV['project']+'-runner-3'
r=subprocess.run(['docker','exec','-i',container,'node'],input=wrapped,capture_output=True,text=True,encoding='utf-8',timeout=120)
h.save('browser-history-final.json',{'at':h.now(),'sha':h.SHA,'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr});assert r.returncode==0,h.clean(r.stderr)
d=json.loads(r.stdout);assert not d['errors']
c=h.cmd(['docker','cp',container+':/tmp/d3-history-final.png',str(h.ROOT/'ui-history-final.png')]);assert c['returncode']==0
print('Final UI history:4 rows, exact API match, all terminal')
